WITH with_windows AS (SELECT id, product_name, price, launch_date, supplier_id, NTILE(5) OVER (PARTITION BY brand ORDER BY cost, id) AS cost_bucket, LAST_VALUE(brand, TRUE) OVER (PARTITION BY supplier_id ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_brand FROM products WHERE cost > 490) SELECT id, product_name, launch_date, supplier_id, cost_bucket, CASE WHEN product_name RLIKE '^(Noise-Cancel Headphones|Yoga Mat)$' THEN 'GROUP_A' ELSE 'EXTENDED' END AS product_name_zone FROM with_windows;
